package main

import (
	"bufio"
	"fmt"
	"os"
)

var mod int64 = 998244353
var pow []int64

func ggt(a, b int64) int64 {
	if a < b {
		return ggt(b, a)
	}
	if b == 0 {
		return a
	}
	return ggt(b, a%b)
}

func gcd(a, b int64) int64 {
	return a * b / ggt(a, b)
}

func gcdRange(n int64) int {
	var g int64 = 1
	for i := int64(1); i <= n; i++ {
		g = gcd(g, i)
	}
	return int(g)
}

func init_(n int64, k int) {
	pow = make([]int64, k)
	pow[0] = 1
	for i := 1; i < k; i++ {
		pow[i] = (n * pow[i-1]) % mod
	}
}

func solve(n int, a, x, y int64, k int, M int64) {
	init_(int64(n), k)

	gcdR := gcdRange(int64(k - 1))

	r := make([][]int64, gcdR)
	for i := range r {
		r[i] = make([]int64, k+1)
	}

	for i := 1; i <= k; i++ {
		for j := 0; j < gcdR; j++ {
			jump := j - (j % (k + 1 - i))
			r[j][i] = (((int64(n)-1)*r[j][i-1])%mod + (r[jump][i-1] + int64(j)*pow[i-1])) % mod
		}
	}

	var sum int64 = 0
	for i := 0; i < n; i++ {
		sum += r[a%int64(gcdR)][k] + (((a/int64(gcdR))*int64(gcdR)*int64(k))%mod)*pow[k-1]%mod
		sum %= mod
		a = (a*x + y) % M
	}

	fmt.Println(sum)
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	var a, x, y int64
	var k int
	var M int64

	fmt.Fscan(reader, &n, &a, &x, &y, &k, &M)

	solve(n, a, x, y, k, M)
}
